	for n := 0; n <= MAXN; n++ {
		C[n][0] = 1
		C[n][n] = 1
		for k := 1; k < n; k++ {
			val := C[n-1][k-1] + C[n-1][k]
			if val > LIM {
				val = LIM
			}
			C[n][k] = val
		}
	}

	// dp[n]: number of good permutations of length n
	dp[0] = 1
	for n := 1; n <= MAXN; n++ {
		var sum int64 = 0
		for m := 1; m <= n; m++ {
			// number of permutations of {1..m} with all cycles having max element first
			// equals (m-1)!; we don't need exact value, only as factor, but we can
			// generate via recurrence using dp-like reasoning:
			// However easier: count of such permutations is (m-1)!,
			// but (m-1)! grows huge; we only need it multiplied with dp[n-m] and C[n-1][m-1], capped at LIM.
			// We'll compute factorial with capping.
		}
	}
}

// compute factorial with capping
func factCap(m int) int64 {
	res := int64(1)
	for i := 2; i <= m; i++ {
		res *= int64(i)
		if res > LIM {
			return LIM
		}
	}
	return res
}

func precomputeDP() {
	for n := 0; n <= MAXN; n++ {
		for k := 0; k <= n; k++ {
			C[n][k] = 0
		}
	}
	for n := 0; n <= MAXN; n++ {
		C[n][0] = 1
		C[n][n] = 1
		for k := 1; k < n; k++ {
