package main

import (
	"bufio"
	"fmt"
	"os"
)

const MAXN = 50
const LIM = int64(1e18)

var dp [MAXN + 1]int64
var sumdp [MAXN + 1]int64

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func precompute() {
	dp[0] = 1
	sumdp[0] = 1
	for n := 1; n <= MAXN; n++ {
		var s int64 = 0
		for m := 1; m <= n; m++ {
			s = min(LIM, s+sumdp[n-m])
		}
		dp[n] = s
		sumdp[n] = min(LIM, sumdp[n-1]+dp[n])
	}
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	precompute()

	// k is 1-based, ensure within bounds
	if k > dp[n] {
		// should not happen per problem statement
		k = dp[n]
	}

	perm := make([]int, 0, n)
	used := make([]bool, n+1)

	for rem := n; rem > 0; {
		// choose cycle length m
		var m int
		for m = 1; m <= rem; m++ {
			cnt := sumdp[rem-m]
			if k > cnt {
				k -= cnt
			} else {
				break
			}
		}

		// choose cycle elements: we need a subset S of size m from remaining numbers
		// with max element first in cycle and remaining m-1 elements in increasing order.
		// We construct S in lexicographic order over permutations, which corresponds to
		// choosing elements in increasing order and using dp for remaining.
		// First, gather remaining numbers.
		remaining := make([]int, 0, rem)
		for v := 1; v <= n; v++ {
			if !used[v] {
				remaining = append(remaining, v)
			}
		}

		// choose the maximum element of the cycle
		var maxIdx int
		for maxIdx = 0; maxIdx < len(remaining); maxIdx++ {
			maxVal := remaining[maxIdx]
			// we choose m-1 elements from remaining[0:maxIdx] (all < maxVal)
			if maxIdx < m-1 {
				continue
			}
			// number of ways to choose subset of size m-1 from maxIdx elements
			// and then permutations of rest: sum over all subsets -> dp[rem-m]
			// but we must count combinations: C(maxIdx, m-1) * dp[rem-m]
			// To avoid big combinatorics, we iterate subsets lexicographically using combinatorial ranking.
			// However n<=50, m<=50, but combinations count can be huge; we only need up to LIM.
			// We'll compute C(maxIdx, m-1) carefully with overflow cap.
			comb := int64(0)
			// compute C(maxIdx, m-1) with cap
			if m-1 == 0 {
				comb = 1
			} else {
				// C(maxIdx, m-1)
				k1 := m - 1
				if k1 > maxIdx-k1 {
					k1 = maxIdx - k1
				}
				num := int64(1)
				den := int64(1)
				for i := 0; i < k1; i++ {
					num = min(LIM, num*int64(maxIdx-i))
					den *= int64(i + 1)
				}
				comb = num / den
			}
			cnt := comb * dp[rem-m]
			if cnt > LIM {
				cnt = LIM
			}
			if k > cnt {
				k -= cnt
			} else {
				break
			}
		}

		maxVal := remaining[maxIdx]
		used[maxVal] = true

		// choose the remaining m-1 elements (all < maxVal) as a subset in lexicographic order
		less := remaining[:maxIdx]
		chosen := make([]int, 0, m-1)

		need := m - 1
		for i := 0; i < len(less) && need > 0; i++ {
			// count subsets that skip less[i]
			remainSlots := len(less) - i - 1
			if remainSlots < need {
				// must take this
				chosen = append(chosen, less[i])
				need--
				continue
			}
			// compute combinations C(remainSlots, need)
			var comb int64
			if need == 0 {
				comb = 1
			} else {
				k1 := need
				if k1 > remainSlots-k1 {
					k1 = remainSlots - k1
				}
				num := int64(1)
				den := int64(1)
				for j := 0; j < k1; j++ {
					num = min(LIM, num*int64(remainSlots-j))
					den *= int64(j + 1)
				}
				comb = num / den
			}
			if k > comb*dp[rem-m] {
				k -= comb * dp[rem-m]
			} else {
				// take this element
				chosen = append(chosen, less[i])
				need--
			}
		}

		for _, v := range chosen {
			used[v] = true
		}

		// build cycle: maxVal first, then chosen in increasing order
		perm = append(perm, maxVal)
		for _, v := range chosen {
			perm = append(perm, v)
		}

		rem -= m
	}

	out := bufio.NewWriter(os.Stdout)
	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, perm[i])
	}
	fmt.Fprintln(out)
	out.Flush()
}

