func main() {
	precompute()

	in := bufio.NewReader(os.Stdin)
	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	// available numbers
	avail := make([]int, n)
	for i := 0; i < n; i++ {
		avail[i] = i + 1
	}

	ans := make([]int, 0, n)
	remaining := n

	for remaining > 0 {
		// choose largest element of next cycle
		maxVal := avail[len(avail)-1]

		// position of maxVal in avail
		pos := len(avail) - 1

		// cycle length from 1 to remaining
		for lenCycle := 1; lenCycle <= remaining; lenCycle++ {
			ways := C[pos][lenCycle-1] * dp[remaining-lenCycle]
			if ways > LIM {
				ways = LIM
			}
			if k > ways {
				k -= ways
			} else {
				// we fix this cycle length
				// choose lenCycle-1 other elements < maxVal
				// we need to find specific subset in lexicographic order
				// generate subset by combinatorial ranking
				subset := make([]int, 0, lenCycle)
				subset = append(subset, maxVal)

