						newAvail = append(newAvail, v)
					}
				}
				avail = newAvail

				// append cycle elements in descending order
				for i := len(subset) - 1; i >= 0; i-- {
					ans = append(ans, subset[i])
				}

				remaining -= lenCycle
				break
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
