var pref [MAXN + 1]int64

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func precompute() {
	dp[0] = 1
	for n := 1; n <= MAXN; n++ {
		dp[n] = 0
		for L := 1; L <= n; L++ {
			dp[n] = min(LIM, dp[n]+dp[n-L])
		}
	}
	pref[0] = dp[0]
	for n := 1; n <= MAXN; n++ {
		pref[n] = min(LIM, pref[n-1]+dp[n])
	}
}

func main() {
	precompute()

	in := bufio.NewReader(os.Stdin)
	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	// find minimal m such that sum_{i=0..m} dp[i] >= k
	m := 0
	for m <= n && pref[m] < k {
		m++
	}
	// k-th among lengths <= m
	var offset int64
	if m == 0 {
		offset = k
	} else {
		offset = k - pref[m-1]
	}

	perm := make([]int, n)
	for i := 0; i < n; i++ {
		perm[i] = i + 1
	}

	pos := 0
	remaining := m
	for remaining > 0 {
		// choose block length L at position pos
		for L := 1; L <= remaining; L++ {
			cnt := dp[remaining-L]
			if offset > cnt {
				offset -= cnt
			} else {
				// apply block of length L starting at pos
				if L >= 2 {
					// rotate right by 1: [a0,a1,...,aL-1] -> [aL-1,a0,...,aL-2]
					last := perm[pos+L-1]
					for i := pos + L - 1; i > pos; i-- {
						perm[i] = perm[i-1]
					}
					perm[pos] = last
				}
				pos += L
				remaining -= L
				break
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, perm[i])
	}
	fmt.Fprintln(out)
	out.Flush()
