			}
		}

		// build cycle starting at cur, length lenCycle
		cycle := make([]int, lenCycle)
		cycle[0] = cur
		used[cur] = true

		for pos := 1; pos < lenCycle; pos++ {
			for v := cur + 1; v <= n; v++ {
				if used[v] {
					continue
				}
				// count permutations if we choose v here
				used[v] = true
				remainingAfter := remaining - lenCycle
				cnt := dp[remainingAfter]
				if cnt >= k {
					cycle[pos] = v
					break
				} else {
					k -= cnt
					used[v] = false
				}
			}
		}

		// write cycle into permutation
		for i := 0; i < lenCycle; i++ {
			from := cycle[i]
			to := cycle[(i+1)%lenCycle]
			if from <= n {
				if len(res) < from {
					for len(res) < from {
						res = append(res, 0)
					}
				}
				res[from-1] = to
			}
		}

		remaining -= lenCycle
		// advance cur to next unused
		for cur <= n && used[cur] {
			cur++
		}
	}

	out := bufio.NewWriter(os.Stdout)
	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, res[i])
	}
	fmt.Fprintln(out)
	out.Flush()
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

const MAXN = 50
const LIM = int64(1e18)

var dp [MAXN + 1]int64

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func precompute() {
	dp[0] = 1
	for n := 1; n <= MAXN; n++ {
		var sum int64 = 0
		for m := 1; m <= n; m++ {
			sum = min(LIM, sum+dp[n-m])
		}
		dp[n] = sum
	}
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	precompute()

	used := make([]bool, n+1)
	ans := make([]int, 0, n)

	for pos := 1; pos <= n; pos++ {
		// find smallest unused number for fixed point
		var smallest int
		for i := 1; i <= n; i++ {
			if !used[i] {
				smallest = i
				break
			}
		}
		// count permutations if we put fixed point here
		remaining := n - pos
		cntFixed := dp[remaining]
		if k <= cntFixed {
			// fixed point
			ans = append(ans, smallest)
			used[smallest] = true
			continue
		}
		k -= cntFixed

		// need to start a cycle here: choose m >=2 and elements
		// first element is smallest unused (smallest), already determined
		// we must choose m-1 other unused elements > smallest
		// but for counting, we only need number of choices: C(cntGreater, m-1)
		// and for each such choice, dp[remaining - (m-1)] permutations
		// first compute list of unused > smallest
		greater := make([]int, 0)
		for i := smallest + 1; i <= n; i++ {
			if !used[i] {
				greater = append(greater, i)
			}
		}
		cntGreater := len(greater)

		// precompute combinations up to cntGreater
		comb := make([][]int64, cntGreater+1)
		for i := 0; i <= cntGreater; i++ {
			comb[i] = make([]int64, cntGreater+1)
		}
		for i := 0; i <= cntGreater; i++ {
			comb[i][0] = 1
			for j := 1; j <= i; j++ {
				val := comb[i-1][j-1] + comb[i-1][j]
				if val > LIM {
					val = LIM
				}
				comb[i][j] = val
			}
		}

		var chosenM int
		for m := 2; m <= cntGreater+1; m++ {
			waysChoose := comb[cntGreater][m-1]
			ways := waysChoose * dp[remaining-(m-1)]
			if ways > LIM {
				ways = LIM
			}
			if k <= ways {
				chosenM = m
				break
			}
			k -= ways
		}

		// now we know cycle length m, need to choose specific m-1 elements from greater
		// in lexicographic order of resulting permutation.
		// cycle will be: smallest, then chosen elements in increasing order.
		// we choose subset of size chosenM-1 in lexicographic order of resulting sequence.
		need := chosenM - 1
		chosen := make([]int, 0, need)

		idx := 0
		for need > 0 {
			if idx >= cntGreater {
				break
			}
			remainingSlots := cntGreater - idx - 1
			// number of subsets including greater[idx]
			waysSub := comb[remainingSlots][need-1]
			ways := waysSub * dp[remaining-(chosenM-1)]
			if ways > LIM {
				ways = LIM
			}
			if k <= ways {
				chosen = append(chosen, greater[idx])
				need--
			} else {
				k -= ways
			}
			idx++
		}

		// build cycle sequence
		cycle := make([]int, 0, chosenM)
		cycle = append(cycle, smallest)
		for _, v := range chosen {
			cycle = append(cycle, v)
		}
		// append to answer and mark used
		for _, v := range cycle {
			ans = append(ans, v)
			used[v] = true
		}
		// advance pos accordingly
		pos += chosenM - 1
	}

	out := bufio.NewWriter(os.Stdout)
	for i := 0; i < n; i++ {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, ans[i])
	}
	fmt.Fprintln(out)
	out.Flush()
}
